class NomPeriodoPago extends BaseNomPeriodoPago {

    /**
     * Obtener un listado de los datos de los periodos de pago.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los periodos de pago.
     */
    public static function obtenerListadoPeriodosPago($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de periodos de pago en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomPeriodoPago')
                ->limit($limite)
                ->offset($inicio)
				->orderBy('denominacion')
                ->fetchArray():
        $query->from('NomPeriodoPago')
				->orderBy('denominacion')
                ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de periodos de pago.
     * 
     * @return int      Cantidad total de periodos de pago.
     */
    public static function obtenerCantidadTotalPeriodosPago() {

        //Devolviendo la cantidad total de periodos d epago.
        return Doctrine_Query::create()->select('COUNT(idperiodopago) AS cantidad')
                        ->from('NomPeriodoPago')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el periodo de pago dado el identificador.
     * 
     * @param int $idperiodo    Identificador del periodo de pago.
     * @return NomPeriodoPago   Objeto periodo de pago (clase del dominio).
     */
    public static function obtenerObjPeriodoPagoDadoId($idperiodo) {
        return Doctrine::getTable('NomPeriodoPago')->find($idperiodo);
    }
  
	/**
     * Obtener si existe un per�odo de pago a partir de la denominaci�n y la cantidad de d�as.
     * 
	 * @param int $idperp    		Identificador del periodo de pago.
	 * @param string $cantd    	 	Cantidad de d�as del periodo de pago.
     * @param string $denom    	 	Denominaci�n del periodo de pago.
	 *
     * @return boolean    			Si existe el per�odo de pago.
     */
    public static function existePeriodoPago($idperp, $cantd, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idperiodopago) AS cantidad')
                        ->from('NomPeriodoPago');
		if($denom){
			$query->addWhere("denominacion ilike ?", $denom);
		}				
		if($idperp){
			$query->addWhere('idperiodopago <> ?', $idperp);
		}	
		if($cantd){
			$query->addWhere("cantidaddias = ?", $cantd);
		}
		return    $query->fetchOne()->cantidad;
     }





  
  
  
  
  
  

/*******************************VER DESDE AQUI*********************************************************/  
    public static function obtenerListadoPeriodosPagoActivos() {

        //Devolviendo el listado de sistemas de pago en forma de arreglo.
        return Doctrine_Query::create()
				->select("idperiodopago, 'P-'||idperiodopago as id, idperiodopago as _id, denominacion, denominacion as text, fechainicio, fechafin, descripcion")
                ->from('NomPeriodoPago')
                ->where('fechafin is null or fechafin <= now()')
                ->fetchArray();
    }
    
    public static function obtenerCantDiasPeriodoPago($cantdias) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->select('p.cantidaddias')
                 ->from('NomPeriodoPago p')
                 ->where("p.cantidaddias=?", array($cantdias))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
        if(count($result)){
		   return 2;	
	         }else{
		   return 1;
		 }
   }
   
   public static function existeDenominacionPeriodoPago($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomPeriodoPago p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }


    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idperiodopago = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomPeriodoPago')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idperiodopago)) {
                $query->andWhere("idperiodopago <> ?", $idperiodopago);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }
}
